// reset updates the index and worktree without changing references. Checkout
// switches HEAD afterward; Reset and Pull move the current branch afterward.
func (w *Worktree) reset(opts *ResetOptions) error {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			trace.Performance.Printf("performance: %.9f s: reset_worktree", time.Since(start).Seconds())
		}()
	}

	if err := opts.Validate(w.r); err != nil {
		return err
	}

	cfg, err := w.r.Config()
	if err != nil {
		return err
	}

	if opts.Mode == MergeReset {
		unstaged, err := w.containsUnstagedChanges(cfg)
		if err != nil {
			return err
		}

		if unstaged {
			return ErrUnstagedChanges
		}
	}

	if opts.Mode == SoftReset {
		return nil
	}

	t, err := w.r.getTreeFromCommitHash(opts.Commit)
	if err != nil {
		return err
	}

	if len(opts.SparseDirs) > 0 && !opts.SkipSparseDirValidation {
		if !treeContainsDirs(t, opts.SparseDirs) {
			return ErrSparseResetDirectoryNotFound
		}
	}

	var trackedChanges merkletrie.Changes
	if err != nil {
		return err
	}

	head, err := w.r.Head()
	if err == nil {
		// if we don't have a shallows list, just ignore it
		shallowList, _ := w.r.Storer.Shallow()

		headAheadOfRef, err := isFastForward(w.r.Storer, ref.Hash(), head.Hash(), shallowList)
		if err != nil {
			return err
		}

		if !updated && headAheadOfRef {
			return NoErrAlreadyUpToDate
		}

		ff, err := isFastForward(w.r.Storer, head.Hash(), ref.Hash(), shallowList)
		if err != nil {
			return err
		}

		if !ff {
			return ErrNonFastForwardUpdate
		}
	}

	if err != nil && !errors.Is(err, plumbing.ErrReferenceNotFound) {
		return err
	}

